contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function with inputs: target callee and arbitrary calldata
    function run(address callee, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        // Read balance before calling
        uint balBefore = address(c).balance;

        bool reverted;
        // perform the call and capture whether c.forward reverts
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        /* General rule asserted:
           If the callee is this test contract (i.e., c.forward attempts to call back into this contract),
           then c.forward must either revert (propagating failure) or succeed without changing c's balance.
           In other words: for callee == address(this), (reverted == true) || (balAfter == balBefore).
        */
        assert(callee != address(this) ? true : (reverted || balAfter == balBefore));
    }

    // allow receiving ETH if the forwarded call tries to send
    receive() external payable {}
}

